import {Label} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import type {CheckJobResponse} from '../types/check-job'
import styles from '../routes/license-compliance.module.css'

interface CheckJobRow {
  id: string
  field: string
  value: string
  isStatus?: boolean
  isCode?: boolean
}

export function CheckJobDetailsTable({checkJob}: {checkJob: CheckJobResponse}) {
  const checkJobData: CheckJobRow[] = [
    {id: 'id', field: 'ID', value: String(checkJob.id)},
    {id: 'status', field: 'Status', value: checkJob.status, isStatus: true},
    {id: 'check_started_at', field: 'Check Started At', value: checkJob.check_started_at || 'N/A'},
    {
      id: 'pull_request',
      field: 'Pull Request',
      value: `#${checkJob.pull_request_number} (ID: ${checkJob.pull_request_id})`,
    },
    {id: 'repository_id', field: 'Repository ID', value: String(checkJob.repository_id)},
    {id: 'organization_id', field: 'Organization ID', value: String(checkJob.organization_id)},
    {
      id: 'enterprise_id',
      field: 'Enterprise ID',
      value: checkJob.enterprise_id ? String(checkJob.enterprise_id) : 'N/A',
    },
    {id: 'base_sha', field: 'Base SHA', value: checkJob.base_sha, isCode: true},
    {id: 'commit_sha', field: 'Commit SHA', value: checkJob.commit_sha, isCode: true},
    {
      id: 'snapshots',
      field: 'Snapshots',
      value: `${checkJob.received_snapshots} / ${checkJob.expected_snapshots} received`,
    },
  ]

  return (
    <Table.Container data-testid="check-job-details">
      <Table.Title as="h3" id="checkjob-details">
        Check Job Details
      </Table.Title>
      <DataTable
        aria-labelledby="checkjob-details"
        data={checkJobData}
        columns={[
          {
            header: 'Field',
            field: 'field',
            rowHeader: true,
            width: '200px',
          },
          {
            header: 'Value',
            field: 'value',
            renderCell: row => {
              if (row.isStatus) {
                return <StatusLabel status={row.value} />
              }
              if (row.isCode) {
                return <code className={styles.monospace}>{row.value}</code>
              }
              return row.value
            },
          },
        ]}
      />
    </Table.Container>
  )
}

function StatusLabel({status}: {status: string}) {
  const variant = status === 'pass' ? 'success' : status === 'fail' ? 'danger' : 'secondary'

  return (
    <Label variant={variant} data-testid="status-label">
      {status}
    </Label>
  )
}
