import {useMemo} from 'react'
import {DataTable, Table} from '@primer/react/experimental'
import type {AllowedLicense} from '../types/route'
import {DEFAULT_PAGE_SIZE} from '../types/constants'
import {usePaginatedData} from '../hooks/use-paginated-data'
import styles from '../routes/license-compliance.module.css'

interface AllowedLicensesTableProps {
  licenses: AllowedLicense[]
  pageSize?: number
}

type LicenseWithId = AllowedLicense & {id: string}

export function AllowedLicensesTable({licenses, pageSize = DEFAULT_PAGE_SIZE}: AllowedLicensesTableProps) {
  const tableId = 'allowed-licenses-table'

  const licensesWithId = useMemo<LicenseWithId[]>(
    () => licenses.map(license => ({...license, id: license.spdxId})),
    [licenses],
  )

  const {paginatedData, totalCount, showPagination, onPageChange} = usePaginatedData(licensesWithId, {pageSize})

  if (licenses.length === 0) {
    return <p className={styles.noAlerts}>No allowed licenses configured.</p>
  }

  return (
    <Table.Container data-testid={tableId}>
      <DataTable
        aria-labelledby={tableId}
        data={paginatedData}
        columns={[
          {
            header: 'SPDX ID',
            field: 'spdxId',
            renderCell: row => row.spdxId || 'N/A',
          },
          {
            header: 'Level',
            field: 'level',
            width: '140px',
            renderCell: row => row.level || 'N/A',
          },
          {
            header: 'Added At',
            field: 'addedAt',
            width: '180px',
            renderCell: row => row.addedAt || 'N/A',
          },
        ]}
      />
      {showPagination && (
        <Table.Pagination
          aria-label="Allowed licenses pagination"
          pageSize={pageSize}
          totalCount={totalCount}
          onChange={pageInfo => onPageChange(pageInfo.pageIndex)}
        />
      )}
    </Table.Container>
  )
}
