import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useState, useCallback, useMemo} from 'react'
import type {CheckJobResponse, CheckJobErrorResponse, DestroyCheckJobResponse} from '../types/check-job'
import type {StafftoolsAlert, AlertsErrorResponse, AlertsResponse} from '../types/alerts'

export interface UseLicenseComplianceDataResult {
  prNumber: string
  setPrNumber: (value: string) => void
  checkJob: CheckJobResponse | null
  alerts: StafftoolsAlert[]
  error: string | null
  alertsError: string | null
  loading: boolean
  resetMessage: string | null
  fetchLicenseData: () => Promise<void>
  resetCheckJob: () => Promise<void>
  openAlerts: StafftoolsAlert[]
  closedAlerts: StafftoolsAlert[]
  hasSearched: boolean
}

export function useLicenseComplianceData(nwo: string): UseLicenseComplianceDataResult {
  const [prNumber, setPrNumber] = useState('')
  const [checkJob, setCheckJob] = useState<CheckJobResponse | null>(null)
  const [alerts, setAlerts] = useState<StafftoolsAlert[]>([])
  const [error, setError] = useState<string | null>(null)
  const [alertsError, setAlertsError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [resetMessage, setResetMessage] = useState<string | null>(null)
  const [hasSearched, setHasSearched] = useState(false)

  const fetchLicenseData = useCallback(async () => {
    if (!prNumber) {
      setError('Please enter a pull request number')
      return
    }

    setLoading(true)
    setError(null)
    setAlertsError(null)
    setResetMessage(null)
    setCheckJob(null)
    setAlerts([])
    setHasSearched(false)

    const checkJobUrl = `/stafftools/repositories/${nwo}/license_compliance/checkjobs/${prNumber}.json`
    const alertsUrl = `/stafftools/repositories/${nwo}/license_compliance/alerts/${prNumber}.json`

    const [checkJobResult, alertsResult] = await Promise.allSettled([
      verifiedFetchJSON(checkJobUrl, {method: 'GET'}),
      verifiedFetchJSON(alertsUrl, {method: 'GET'}),
    ])

    // Handle check job response
    if (checkJobResult.status === 'fulfilled') {
      const response = checkJobResult.value
      if (response.ok) {
        const data = (await response.json()) as CheckJobResponse
        // Only set if we have a valid check job with an ID
        if (data && data.id) {
          setCheckJob(data)
        }
      } else {
        const errorData = (await response.json()) as CheckJobErrorResponse
        setError(errorData.error || 'Failed to fetch check job')
      }
    } else {
      setError('Failed to fetch check job')
    }

    // Handle alerts response
    if (alertsResult.status === 'fulfilled') {
      const response = alertsResult.value
      if (response.ok) {
        const data = (await response.json()) as AlertsResponse
        setAlerts(data.alerts || [])
      } else {
        const errorData = (await response.json()) as AlertsErrorResponse
        setAlertsError(errorData.error || 'Failed to fetch alerts')
      }
    } else {
      setAlertsError('Failed to fetch alerts')
    }

    setHasSearched(true)
    setLoading(false)
  }, [nwo, prNumber])

  const resetCheckJob = useCallback(async () => {
    if (!prNumber) {
      setError('Please enter a pull request number')
      return
    }

    setLoading(true)
    setError(null)
    setAlertsError(null)
    setResetMessage(null)

    const url = `/stafftools/repositories/${nwo}/license_compliance/checkjobs/${prNumber}.json`
    const response = await verifiedFetchJSON(url, {method: 'DELETE'})

    if (response.ok) {
      const data = (await response.json()) as DestroyCheckJobResponse
      if (data.success) {
        setResetMessage(
          'Check job reset successfully. The license compliance check will restart and alerts will be recalculated.',
        )
        setCheckJob(null)
        setAlerts([])
      } else {
        setError('Failed to reset check job')
      }
    } else {
      const errorData = (await response.json()) as CheckJobErrorResponse
      setError(errorData.error || 'Failed to reset check job')
    }

    setLoading(false)
  }, [nwo, prNumber])

  const openAlerts = useMemo(() => alerts.filter(alert => alert.status !== 'closed'), [alerts])
  const closedAlerts = useMemo(() => alerts.filter(alert => alert.status === 'closed'), [alerts])

  return {
    prNumber,
    setPrNumber,
    checkJob,
    alerts,
    error,
    alertsError,
    loading,
    resetMessage,
    fetchLicenseData,
    resetCheckJob,
    openAlerts,
    closedAlerts,
    hasSearched,
  }
}
