import {Stack} from '@primer/react'
import {CheckCircleIcon, XCircleIcon} from '@primer/octicons-react'
import styles from '../routes/license-compliance.module.css'

interface FeatureStatusSectionProps {
  isEnabled: boolean
}

export function FeatureStatusSection({isEnabled}: FeatureStatusSectionProps) {
  return (
    <section>
      <h2 className={styles.sectionTitle}>Feature Status</h2>
      <Stack direction="horizontal" gap="condensed" align="center">
        {isEnabled ? (
          <>
            <CheckCircleIcon size={16} className="fgColor-success" />
            <span>License compliance feature flag is enabled</span>
          </>
        ) : (
          <>
            <XCircleIcon size={16} className="fgColor-danger" />
            <span>License compliance feature flag is disabled</span>
          </>
        )}
      </Stack>
    </section>
  )
}
